
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_r2scanl_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_r2scanl", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.885392040126328e+00, -4.786555800935257e+00, -4.648029164942637e+00, -4.456065958173433e+00, -4.194347411014212e+00, -3.845725674653452e+00, -3.396098821055683e+00, -2.835072060130467e+00, -2.192195272407540e+00, -1.506918660886950e+00, -8.500274184396061e-01, -6.335580822230633e-01, -6.613703495026364e-01, -5.301302538775047e-01, -3.586599666992457e-01, -1.926575898630389e-01, -7.494369204870442e-02, -2.078096863631328e-02, -2.955891001927685e-03, -1.593009973423943e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


